#!/usr/bin/env bash
# Fails if generated code (templ, sqlc) is stale. Snapshots every templ/sqlc output file, deletes them,
# runs `make generate` and compares. Deleting first catches orphans: sqlc never removes the output of a
# deleted query file. Works on a dirty tree; outputs are regenerated either way.
set -eu
cd "$(dirname "$0")/.."

generated() {
  grep -rlE --include='*.go' --exclude-dir=.git \
    '^// Code generated by (templ - DO NOT EDIT|sqlc\. DO NOT EDIT)\.$' . 2>/dev/null | LC_ALL=C sort || true
}
snapshot() { generated | while IFS= read -r f; do shasum -a 256 "$f"; done; }

before=$(snapshot)
generated | while IFS= read -r f; do rm -f "$f"; done
make -s generate >/dev/null
after=$(snapshot)

if [ "$before" != "$after" ]; then
  echo "generate-check: generated code was stale and has been regenerated; review and commit:" >&2
  diff <(echo "$before") <(echo "$after") | grep -E '^[<>]' | awk '{print "  " $3}' | sort -u >&2
  exit 1
fi
echo "generate-check: ok"
